 "content": "def transform(grid):
    # Isolated 8 markers are replaced by the 3-cell legend motif at the bottom.
    # Legend on test is [9,9,9,3,4], motif pattern is 3,4; observed analogues
    # encode directional colors; test marker color 8 maps to 3,4,5 motif.
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # test legend specifies a horizontal 3-wide sequence: 9,3,4 -> 9,3,4
    # Replace each isolated marker with the visible pattern 9,3,4 extending left.
    for r in range(h-1):
        for c in range(w):
            if grid[r][c]==8:
                for k,v in enumerate((9,3,4)):
                    cc=c-2+k
                    if 0<=cc<w: g[r][cc]=v
    return g
